#!/bin/sh
# Downloads and converts the host-provided module data tables into data/.
# Mirrors the macOS host's pipeline (same pinned sources, same conversion):
# wordFrequency is the single-character subset of McBopomofo's phrase.occ
# corpus (MIT). Generated files are not committed; dev-install.sh installs
# them alongside the addon.
set -eu

root="$(cd "$(dirname "$0")/.." && pwd)"
out_dir="$root/data/modules"
mkdir -p "$out_dir"

mcbopomofo_pin="20d86c571d183a7ce7d5f91419b815dea5c3efbc"
occ_url="https://raw.githubusercontent.com/openvanilla/McBopomofo/$mcbopomofo_pin/Source/Data/phrase.occ"
license_url="https://raw.githubusercontent.com/openvanilla/McBopomofo/$mcbopomofo_pin/LICENSE.txt"

occ_file="$root/data/phrase.occ"
if [ ! -f "$occ_file" ]; then
    echo "Downloading phrase.occ ($mcbopomofo_pin)..."
    curl -fsSL "$occ_url" -o "$occ_file"
fi
if [ ! -f "$root/data/McBopomofo.LICENSE.txt" ]; then
    curl -fsSL "$license_url" -o "$root/data/McBopomofo.LICENSE.txt"
fi

python3 - "$occ_file" "$out_dir/wordFrequency.zh-Hant.tsv" "$occ_url" <<'EOF'
import sys

occ_path, out_path, source_url = sys.argv[1:4]
lines = [
    "# Per-character frequency table (single-character subset of the source corpus).",
    "# format: char<TAB>count",
    f"# source: {source_url}",
    "# generated by scripts/prepare-data.sh - DO NOT EDIT",
    "",
]
with open(occ_path, encoding="utf-8") as occ:
    for line in occ:
        parts = line.split(None, 1)
        if len(parts) != 2:
            continue
        key, count = parts[0], parts[1].strip()
        if len(key) == 1:  # exactly one Unicode scalar
            lines.append(f"{key}\t{count}")
with open(out_path, "w", encoding="utf-8") as out:
    out.write("\n".join(lines) + "\n")
print(f"wrote {out_path} ({len(lines) - 5} entries)")
EOF

# symbolNames: CLDR zh-Hant annotations (single BMP symbols, tts name),
# optionally overlaid with the hand-curated override table from a MacishType
# checkout (set MACISHTYPE_REPO to use it; the override wins on conflicts).
cldr_pin="a79b499916d486dca4b0f74fe423ea457705fdd9"
cldr_url="https://raw.githubusercontent.com/unicode-org/cldr-json/$cldr_pin/cldr-json/cldr-annotations-full/annotations/zh-Hant/annotations.json"
cldr_license_url="https://raw.githubusercontent.com/unicode-org/cldr-json/$cldr_pin/LICENSE"

cldr_file="$root/data/cldr-annotations.zh-Hant.json"
if [ ! -f "$cldr_file" ]; then
    echo "Downloading CLDR annotations ($cldr_pin)..."
    curl -fsSL "$cldr_url" -o "$cldr_file"
fi
if [ ! -f "$root/data/CLDR.LICENSE.txt" ]; then
    curl -fsSL "$cldr_license_url" -o "$root/data/CLDR.LICENSE.txt"
fi

override_file="${MACISHTYPE_REPO:+$MACISHTYPE_REPO/Scripts/SymbolNamesOverride.zh-Hant.txt}"
python3 - "$cldr_file" "$out_dir/symbolNames.zh-Hant.tsv" "$cldr_url" \
    "${override_file:-}" <<'EOF'
import json
import sys

cldr_path, out_path, source_url, override_path = sys.argv[1:5]
names = {}
with open(cldr_path, encoding="utf-8") as handle:
    annotations = json.load(handle)["annotations"]["annotations"]
for symbol, value in annotations.items():
    codepoints = [ord(ch) for ch in symbol]
    if len(codepoints) != 1 or codepoints[0] > 0xFFFF:
        continue
    tts = value.get("tts")
    if tts:
        names[symbol] = tts[0]

overlaid = 0
if override_path:
    try:
        with open(override_path, encoding="utf-8") as handle:
            for line in handle:
                line = line.rstrip("\n")
                if not line or line.startswith("#") or "\t" not in line:
                    continue
                symbol, name = line.split("\t", 1)
                names[symbol] = name
                overlaid += 1
    except FileNotFoundError:
        print(f"override not found, skipped: {override_path}")

lines = [
    "# Symbol-to-name table (CLDR zh-Hant annotations, single BMP symbols).",
    "# format: symbol<TAB>name",
    f"# source: {source_url}",
    "# generated by scripts/prepare-data.sh - DO NOT EDIT",
    "",
]
for symbol in sorted(names, key=lambda s: (ord(s[0]), s)):
    lines.append(f"{symbol}\t{names[symbol]}")
with open(out_path, "w", encoding="utf-8") as out:
    out.write("\n".join(lines) + "\n")
print(f"wrote {out_path} ({len(names)} entries, {overlaid} overridden)")
EOF
